Design a circuit that detects the direction of a rotary encoder using two input signals, `rot_a` and `rot_b`. The module outputs a rotation event (`rot_event`) indicating when the encoder is considered active (both inputs are high) and a rotation direction (`rot_dir`) that determines the direction of rotation (1 for clockwise when `rot_a` is low and `rot_b` is high, and 0 for counterclockwise when `rot_a` is high and `rot_b` is low). The circuit updates outputs on the rising edge of the clock signal (`clk`).
module top_module(clk,rot_a,rot_b,rot_event,rot_dir
    );

code:
module top_module(clk,rot_a,rot_b,rot_event,rot_dir
    );input clk,rot_a,rot_b;
output rot_event,rot_dir;
reg rot_event,rot_dir;
always @(posedge clk) begin
	if(rot_a == 1 & rot_b==1)
		rot_event <= 1;
	if(rot_a == 0 & rot_b==0)
		rot_event <= 0;
	if(rot_a == 0 & rot_b==1)
		rot_dir <= 1;
	if(rot_a == 1 & rot_b==0)
		rot_dir <= 0;
end

endmodule

