description:
Implement the Verilog module based on the following description.
We want to create a 3-bit majority voter that:

// (1) takes three 1-bit inputs 'a', 'b', and 'c',
// (2) outputs '1' if at least two of the three inputs are '1',
// (3) outputs '0' otherwise.

// The output value is 'out'.

module top_module(
    input wire a,
    input wire b,
    input wire c,
    output wire out
);

code:
module top_module(
    input wire a,
    input wire b,
    input wire c,
    output wire out
);

    assign out = (a & b) | (a & c) | (b & c);

endmodule

